package com.fasterxml.jackson.core.io;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class NumberInputTrailingDotTest
{
    @Test
    void looksLikeValidNumberShouldAcceptTrailingDotNumbers() {
        assertTrue(NumberInput.looksLikeValidNumber("3."));
        assertTrue(NumberInput.looksLikeValidNumber("+12."));
        assertTrue(NumberInput.looksLikeValidNumber("-5."));
        assertTrue(NumberInput.looksLikeValidNumber("123."));

        // sanity checks for other valid number forms
        assertTrue(NumberInput.looksLikeValidNumber("10.25"));
        assertTrue(NumberInput.looksLikeValidNumber(".00006"));
    }

    @Test
    void looksLikeValidNumberShouldRejectNonNumbers() {
        assertFalse(NumberInput.looksLikeValidNumber(null));
        assertFalse(NumberInput.looksLikeValidNumber(""));
        assertFalse(NumberInput.looksLikeValidNumber("abc"));
        assertFalse(NumberInput.looksLikeValidNumber("."));
        assertFalse(NumberInput.looksLikeValidNumber("+."));
        assertFalse(NumberInput.looksLikeValidNumber("3.."));
    }
}

