package com.fasterxml.jackson.core;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.junit.jupiter.api.Test;

import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;

public class JsonFactoryStreamReadConstraintsTest {

    @Test
    public void setStreamReadConstraintsShouldRecreateRootCharSymbolsWhenMaxNameLengthChanges() {
        JsonFactory factory = new JsonFactory();
        CharsToNameCanonicalizer rootBefore = factory._rootCharSymbols;
        int originalMaxNameLength = factory.streamReadConstraints().getMaxNameLength();

        StreamReadConstraints updatedConstraints = StreamReadConstraints.builder()
                .maxNameLength(originalMaxNameLength + 1)
                .build();

        JsonFactory returned = factory.setStreamReadConstraints(updatedConstraints);

        assertSame(factory, returned, "Method should support fluent chaining");
        assertEquals(originalMaxNameLength + 1, factory.streamReadConstraints().getMaxNameLength(),
                "Factory must retain the newly configured stream read constraints");
        assertNotSame(rootBefore, factory._rootCharSymbols,
                "Root symbol table should be recreated when maxNameLength changes");
    }
}

