package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.util.JsonParserDelegate;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

public class GetNumberTypeFPTest {

    @Test
    public void testGetNumberTypeFP_OnFloatToken_TextualParser_ReturnsUnknown() throws IOException {
        JsonFactory f = new JsonFactory();
        try (JsonParser p = f.createParser("1.25")) {
            JsonToken t = p.nextToken();
            assertEquals("Expected a floating-point number token", JsonToken.VALUE_NUMBER_FLOAT, t);

            JsonParser.NumberTypeFP typeFP = p.getNumberTypeFP();
            assertNotNull("getNumberTypeFP() must never return null", typeFP);
            assertSame("Textual parsers should report UNKNOWN FP type", JsonParser.NumberTypeFP.UNKNOWN, typeFP);

            // Ensure calling does not change current token
            assertEquals(JsonToken.VALUE_NUMBER_FLOAT, p.currentToken());
        }
    }

    @Test
    public void testGetNumberTypeFP_OnIntegerToken_TextualParser_ReturnsUnknown() throws IOException {
        JsonFactory f = new JsonFactory();
        try (JsonParser p = f.createParser("123")) {
            JsonToken t = p.nextToken();
            assertEquals("Expected an integer number token", JsonToken.VALUE_NUMBER_INT, t);

            JsonParser.NumberTypeFP typeFP = p.getNumberTypeFP();
            assertNotNull("getNumberTypeFP() must never return null", typeFP);
            assertSame("For integer tokens, FP type should be UNKNOWN", JsonParser.NumberTypeFP.UNKNOWN, typeFP);
        }
    }

    @Test
    public void testGetNumberTypeFP_Delegation_InJsonParserDelegate() throws IOException {
        JsonFactory f = new JsonFactory();
        try (JsonParser underlying = f.createParser("0.5")) {
            JsonParserDelegate delegate = new JsonParserDelegate(underlying);

            // Advance to the first token
            JsonToken dt = delegate.nextToken();
            assertEquals(JsonToken.VALUE_NUMBER_FLOAT, dt);
            // Underlying parser should be in sync
            assertEquals(JsonToken.VALUE_NUMBER_FLOAT, underlying.currentToken());

            // Both underlying parser and delegate should return the same FP type
            JsonParser.NumberTypeFP underlyingType = underlying.getNumberTypeFP();
            JsonParser.NumberTypeFP delegatedType = delegate.getNumberTypeFP();

            assertNotNull(underlyingType);
            assertNotNull(delegatedType);
            assertSame("Delegate should return the same FP type as the underlying parser",
                    underlyingType, delegatedType);

            // For textual JSON, FP type is expected to be UNKNOWN by default
            assertSame(JsonParser.NumberTypeFP.UNKNOWN, delegatedType);
        }
    }
}

