package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import org.junit.Assert;
import org.junit.Test;

public class JsonParserNumberTypeFPTest {

    @Test
    public void testGetNumberTypeFPReturnsUnknownForTextualFloats() throws Exception {
        JsonFactory f = new JsonFactory();
        JsonParser p = f.createParser("0.1");

        JsonToken t = p.nextToken();
        Assert.assertEquals("Expected a floating-point number token", JsonToken.VALUE_NUMBER_FLOAT, t);

        JsonParser.NumberTypeFP typeFP = p.getNumberTypeFP();
        Assert.assertNotNull("NumberTypeFP must never be null", typeFP);
        Assert.assertEquals("Textual JSON parser should report UNKNOWN for FP type", JsonParser.NumberTypeFP.UNKNOWN, typeFP);

        p.close();
    }

    @Test
    public void testJsonParserDelegateDelegatesGetNumberTypeFP() throws Exception {
        JsonFactory f = new JsonFactory();
        JsonParser base = f.createParser("1.25");

        // First-level delegate that overrides getNumberTypeFP to simulate a parser
        // that knows its explicit FP type (e.g., binary format parser)
        JsonParserDelegate firstDelegate = new JsonParserDelegate(base) {
            @Override
            public JsonParser.NumberTypeFP getNumberTypeFP() {
                return JsonParser.NumberTypeFP.DOUBLE64;
            }
        };

        // Second-level delegate is the class under test: it should delegate calls to the underlying parser
        JsonParserDelegate underTest = new JsonParserDelegate(firstDelegate);

        JsonToken t = underTest.nextToken();
        Assert.assertEquals("Expected a floating-point number token", JsonToken.VALUE_NUMBER_FLOAT, t);

        // With the patch, JsonParserDelegate.getNumberTypeFP() delegates to the underlying parser.
        // Without the patch, it would have returned UNKNOWN regardless.
        JsonParser.NumberTypeFP delegatedType = underTest.getNumberTypeFP();
        Assert.assertNotNull("Delegated NumberTypeFP must never be null", delegatedType);
        Assert.assertEquals("JsonParserDelegate should delegate getNumberTypeFP to the underlying parser",
                JsonParser.NumberTypeFP.DOUBLE64, delegatedType);

        underTest.close();
    }
}

