package com.fasterxml.jackson.core;

import org.junit.Test;

import static org.junit.Assert.*;

public class JsonPointerAppendTailTest {

    @Test
    public void appendTailFromTailPointerShouldIgnoreOriginalPrefix() {
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tail = original.tail(); // represents "/b/c"
        JsonPointer other = JsonPointer.compile("/a2");

        JsonPointer combined = other.append(tail);

        assertEquals("/a2/b/c", combined.toString());
        assertEquals(JsonPointer.compile("/a2/b/c"), combined);
    }

    @Test
    public void appendOnPointerWithTrailingSlashPreservesEmptySegment() {
        // Build a pointer that ends with a trailing slash via appendProperty("")
        JsonPointer current = JsonPointer.compile("/a").appendProperty("");
        assertEquals("/a/", current.toString());

        JsonPointer tail = JsonPointer.compile("/b");
        JsonPointer result = current.append(tail);

        // The empty segment between 'a' and 'b' must be preserved
        assertEquals("/a//b", result.toString());
        assertEquals(JsonPointer.compile("/a//b"), result);
    }

    @Test
    public void appendIndexDoesNotStripTrailingSlash() {
        // Build a pointer that ends with a trailing slash via appendProperty("")
        JsonPointer current = JsonPointer.compile("/a").appendProperty("");
        assertEquals("/a/", current.toString());

        JsonPointer withIndex = current.appendIndex(3);

        // The empty segment between 'a' and '3' must be preserved
        assertEquals("/a//3", withIndex.toString());
        assertEquals(JsonPointer.compile("/a//3"), withIndex);
    }

    @Test
    public void appendPropertyRespectsTailOffset() {
        JsonPointer base = JsonPointer.compile("/x/y");
        JsonPointer tail = base.tail(); // represents "/y" (shares backing string with offset)

        JsonPointer appended = tail.appendProperty("z");

        // Must use the tail's offset; should not re-use original base prefix
        assertEquals("/y/z", appended.toString());
        assertEquals(JsonPointer.compile("/y/z"), appended);
    }

    @Test
    public void appendIndexRespectsTailOffset() {
        JsonPointer base = JsonPointer.compile("/x/y");
        JsonPointer tail = base.tail(); // represents "/y"

        JsonPointer appendedIdx = tail.appendIndex(2);

        // Must use the tail's offset; should not re-use original base prefix
        assertEquals("/y/2", appendedIdx.toString());
        assertEquals(JsonPointer.compile("/y/2"), appendedIdx);
    }

    @Test
    public void appendWithEmptyPointerOptimization() {
        JsonPointer empty = JsonPointer.empty();
        JsonPointer a = JsonPointer.compile("/a");

        // Appending an empty tail should return the original pointer instance
        assertSame(a, a.append(empty));

        // Appending to an empty 'this' should return the tail instance
        assertSame(a, empty.append(a));
    }
}

