package com.fasterxml.jackson.core;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class JsonPointerAppendAndPropertyTest {

    @Test
    public void appendWithTailShouldNotIncludeOriginalHead() {
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tail = original.tail();
        assertEquals("/b/c", tail.toString(), "Tail pointer should represent '/b/c'");

        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tail);

        assertEquals("/a2/b/c", concatenated.toString(),
                "Appending tail should not include original head '/a1'");
    }

    @Test
    public void appendPropertyOnTailShouldRespectOffsetAndEscape() {
        JsonPointer original = JsonPointer.compile("/root/child");
        JsonPointer tail = original.tail(); // represents "/child"
        assertEquals("/child", tail.toString());

        // Property contains '/' and '~' that must be escaped
        JsonPointer withProp = tail.appendProperty("na/me~x");

        // "/" -> "~1", "~" -> "~0"
        assertEquals("/child/na~1me~0x", withProp.toString(),
                "appendProperty must respect tail offset and escape properly");

        // Ensure original head is not included inadvertently
        assertNotEquals("/root/child/na~1me~0x", withProp.toString(),
                "appendProperty on a tail pointer must not include original head");
    }

    @Test
    public void appendIndexOnTailShouldRespectOffset() {
        JsonPointer original = JsonPointer.compile("/parent/child");
        JsonPointer tail = original.tail(); // represents "/child"
        assertEquals("/child", tail.toString());

        JsonPointer withIndex = tail.appendIndex(3);
        assertEquals("/child/3", withIndex.toString(),
                "appendIndex on a tail pointer must not include original head");
    }

    @Test
    public void appendShouldPreserveTrailingSlashEmptyToken() {
        JsonPointer head = JsonPointer.compile("/a/");
        JsonPointer tail = JsonPointer.compile("/b");

        JsonPointer out = head.append(tail);

        // Trailing slash in head indicates an empty reference token; it must be preserved
        assertEquals("/a//b", out.toString(),
                "Appending must preserve empty token from trailing slash in head");
        assertNotEquals("/a/b", out.toString(),
                "Legacy behavior incorrectly removed trailing slash; must not do that");
    }

    @Test
    public void appendIndexShouldPreserveTrailingSlashEmptyToken() {
        JsonPointer head = JsonPointer.compile("/a/");

        JsonPointer out = head.appendIndex(1);

        // Trailing slash indicates empty token; appending index should not trim it
        assertEquals("/a//1", out.toString(),
                "appendIndex must preserve empty token from trailing slash in head");
        assertNotEquals("/a/1", out.toString(),
                "Legacy behavior incorrectly removed trailing slash; must not do that");
    }

    @Test
    public void appendPropertyNullReturnsThis() {
        JsonPointer ptr = JsonPointer.compile("/x/y");
        JsonPointer out = ptr.appendProperty(null);
        assertSame(ptr, out, "appendProperty(null) should return the same instance");
    }
}

