        JsonPointer tail = JsonPointer.compile("/b");

        JsonPointer result = baseWithTrailingSlash.append(tail);
        // Trailing slash should be preserved, leading to an empty segment between 'a' and 'b'
        assertEquals("/a//b", result.toString());

        // Also verify the same behavior when appending an index
        JsonPointer resultIdx = baseWithTrailingSlash.appendIndex(3);
        assertEquals("/a//3", resultIdx.toString());
