import org.junit.Test;

import static org.junit.Assert.*;

public class VersionEqualsHashCodeNullSnapshotTest {

    @Test
    public void testEqualsWithNullAndNonNullSnapshot_NoNPEAndFalse() {
        Version vNullSnapshot = new Version(1, 2, 3, null, "com.example", "my-artifact");
        Version vNonNullSnapshot = new Version(1, 2, 3, "SNAPSHOT", "com.example", "my-artifact");

        // Should not throw NPE and should be false since snapshot infos differ (null vs non-null)
        assertFalse(vNullSnapshot.equals(vNonNullSnapshot));
        assertFalse(vNonNullSnapshot.equals(vNullSnapshot));
    }

    @Test
    public void testEqualsWithBothNullSnapshots_TrueAndHashCodeEqual() {
        Version v1 = new Version(2, 5, 0, null, "com.example", "lib");
        Version v2 = new Version(2, 5, 0, null, "com.example", "lib");

        // Reflexivity
        assertTrue(v1.equals(v1));

        // Symmetry and equality when both snapshot infos are null and other fields equal
        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v1));

        // Equal objects must have equal hash codes; also verifies no NPE in hashCode
        assertEquals(v1.hashCode(), v2.hashCode());
    }

    @Test
    public void testHashCodeWithNullSnapshot_NoNPE() {
        Version v = new Version(0, 9, 10, null, "com.acme", "util");
        // Should not throw NPE
        int hc = v.hashCode();
        // Just a basic sanity check that hash code is a stable int value
        assertNotEquals("Hash code should not be zero by coincidence in this setup", 0, hc ^ 0);
    }

