    public void testEqualsDifferOnlyBySnapshot_EmptyVsNull() {
        Version vNull = new Version(3, 1, 4, null, "org.sample", "core");
        Version vEmpty = new Version(3, 1, 4, "", "org.sample", "core");

        // Objects.equals(null, "") is false; ensure no NPE and equality reflects that
        assertFalse(vNull.equals(vEmpty));
        assertFalse(vEmpty.equals(vNull));
    }
