package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.async.ByteArrayFeeder;
import com.fasterxml.jackson.core.async.ByteBufferFeeder;
import com.fasterxml.jackson.core.json.async.NonBlockingJsonParser;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class CanonicalizeFieldNamesFeatureTest {

    private static final String JSON_WITH_DUP_FIELD_NAMES = "[{\"fieldNameRepeated\":1},{\"fieldNameRepeated\":2}]";

    @Test
    public void testNonBlockingByteArrayParser_RespectsCanonicalizeFieldNames() throws Exception {
        byte[] json = JSON_WITH_DUP_FIELD_NAMES.getBytes("UTF-8");

        // Disabled: should NOT canonicalize -> distinct String instances for same field name
        JsonFactory factoryDisabled = new JsonFactory();
        factoryDisabled.disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);
        List<String> namesDisabled = readFieldNamesFromNonBlockingByteArray(factoryDisabled, json);
        assertTrue("Expected at least two FIELD_NAME tokens", namesDisabled.size() >= 2);
        assertEquals("fieldNameRepeated", namesDisabled.get(0));
        assertEquals("fieldNameRepeated", namesDisabled.get(1));
        assertNotSame("Field name instances should not be identical when canonicalization is disabled",
                namesDisabled.get(0), namesDisabled.get(1));

        // Enabled: should canonicalize -> same String instance reused
        JsonFactory factoryEnabled = new JsonFactory();
        factoryEnabled.enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);
        List<String> namesEnabled = readFieldNamesFromNonBlockingByteArray(factoryEnabled, json);
        assertTrue("Expected at least two FIELD_NAME tokens", namesEnabled.size() >= 2);
