import java.io.IOException;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class Base64MissingPaddingTest {

    private static Base64Variant allowedPaddingVariant() {
        return Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
    }

    private static Base64Variant requiredPaddingVariant() {
        return Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_REQUIRED);
    }

    @Test
    void readerBasedParserAllowsMissingPaddingForOneByteValue() throws Exception {
        JsonFactory factory = new JsonFactory();
        byte[] expected = new byte[] { 65 }; // "QQ" -> 'A'

        try (JsonParser p = factory.createParser(new StringReader("\"QQ\""))) {
            assertEquals(JsonToken.VALUE_STRING, p.nextToken());
            assertArrayEquals(expected, p.getBinaryValue(allowedPaddingVariant()));
        }
    }

    @Test
    void utf8StreamParserAllowsMissingPaddingForTwoByteValue() throws Exception {
        JsonFactory factory = new JsonFactory();
        byte[] expected = new byte[] { 1, 2 };
        byte[] json = "\"AQI\"".getBytes(StandardCharsets.UTF_8);

        try (JsonParser p = factory.createParser(json)) {
            assertEquals(JsonToken.VALUE_STRING, p.nextToken());

            ByteArrayOutputStream out = new ByteArrayOutputStream();
            int written = p.readBinaryValue(allowedPaddingVariant(), out);

            assertEquals(expected.length, written);
            assertArrayEquals(expected, out.toByteArray());
        }
    }

    @Test
    void utf8DataInputParserAllowsMissingPadding() throws Exception {
        JsonFactory factory = new JsonFactory();
        byte[] expected = new byte[] { 1, 2 };
        byte[] json = "\"AQI\"".getBytes(StandardCharsets.UTF_8);

        try (JsonParser p = factory.createParser((DataInput) new DataInputStream(new ByteArrayInputStream(json)))) {
            assertEquals(JsonToken.VALUE_STRING, p.nextToken());
            assertArrayEquals(expected, p.getBinaryValue(allowedPaddingVariant()));
        }
    }

    @Test
    void missingPaddingStillFailsWhenPaddingIsRequired() throws Exception {
        JsonFactory factory = new JsonFactory();

        try (JsonParser p = factory.createParser(new StringReader("\"AQI\""))) {
            assertEquals(JsonToken.VALUE_STRING, p.nextToken());
            assertThrows(IOException.class, () -> p.getBinaryValue(requiredPaddingVariant()));
        }
    }
}

