import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class Base64PaddingReadBehaviourTest {

    private static final Base64Variant VARIANT_PADDING_ALLOWED =
            Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

    private static final Base64Variant VARIANT_PADDING_REQUIRED =
            Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_REQUIRED);

    private static final String JSON_TEMPLATE = "{\"b\":\"%s\"}";

    // Helpers to create different parser types
    private JsonParser createUtf8StreamParser(JsonFactory f, String json) throws Exception {
        byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
        return f.createParser(bytes);
    }

    private JsonParser createReaderParser(JsonFactory f, String json) throws Exception {
        return f.createParser(new StringReader(json));
    }

    private JsonParser createDataInputParser(JsonFactory f, String json) throws Exception {
        byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
        DataInput di = new DataInputStream(new ByteArrayInputStream(bytes));
        return f.createParser(di);
    }

    private static void advanceToValueString(JsonParser p) throws Exception {
        assertEquals(JsonToken.START_OBJECT, p.nextToken());
        assertEquals(JsonToken.FIELD_NAME, p.nextToken());
        assertEquals("b", p.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, p.nextToken());
    }

    private static byte[] decodeWithGetBinaryValue(JsonParser p, Base64Variant variant) throws Exception {
        advanceToValueString(p);
        byte[] data = p.getBinaryValue(variant);
        assertEquals(JsonToken.END_OBJECT, p.nextToken());
        return data;
    }

    private static byte[] decodeWithReadBinaryValue(JsonParser p, Base64Variant variant) throws Exception {
        advanceToValueString(p);
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int count = p.readBinaryValue(variant, out);
        byte[] data = out.toByteArray();
        assertEquals(data.length, count);
        assertEquals(JsonToken.END_OBJECT, p.nextToken());
        return data;
    }

    // UTF8StreamJsonParser: verify both 2-char and 3-char tail without padding for both _decodeBase64 and _readBinary
    @Test
    public void testUtf8StreamParser_MissingPaddingAllowed_twoAndThreeChars() throws Exception {
        JsonFactory f = JsonFactory.builder().build();

        // 2 Base64 chars -> 1 decoded byte (0x01), no '=' padding
        String json2 = String.format(JSON_TEMPLATE, "AQ");
        try (JsonParser p = createUtf8StreamParser(f, json2)) {
            byte[] data = decodeWithGetBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01 }, data);
        }
        try (JsonParser p = createUtf8StreamParser(f, json2)) {
            byte[] data = decodeWithReadBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01 }, data);
        }

        // 3 Base64 chars -> 2 decoded bytes (0x01, 0x02), no '=' padding
        String json3 = String.format(JSON_TEMPLATE, "AQI");
        try (JsonParser p = createUtf8StreamParser(f, json3)) {
            byte[] data = decodeWithGetBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01, 0x02 }, data);
        }
        try (JsonParser p = createUtf8StreamParser(f, json3)) {
            byte[] data = decodeWithReadBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01, 0x02 }, data);
        }
    }

    // ReaderBasedJsonParser: verify both 2-char and 3-char tail for both methods
    @Test
    public void testReaderBasedParser_MissingPaddingAllowed_twoAndThreeChars() throws Exception {
        JsonFactory f = JsonFactory.builder().build();

        String json2 = String.format(JSON_TEMPLATE, "AQ");
        try (JsonParser p = createReaderParser(f, json2)) {
            byte[] data = decodeWithGetBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01 }, data);
        }
        try (JsonParser p = createReaderParser(f, json2)) {
            byte[] data = decodeWithReadBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01 }, data);
        }

        String json3 = String.format(JSON_TEMPLATE, "AQI");
        try (JsonParser p = createReaderParser(f, json3)) {
            byte[] data = decodeWithGetBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01, 0x02 }, data);
        }
        try (JsonParser p = createReaderParser(f, json3)) {
            byte[] data = decodeWithReadBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01, 0x02 }, data);
        }
    }

    // UTF8DataInputJsonParser: verify both 2-char and 3-char tail for both methods
    @Test
    public void testDataInputParser_MissingPaddingAllowed_twoAndThreeChars() throws Exception {
        JsonFactory f = JsonFactory.builder().build();

        String json2 = String.format(JSON_TEMPLATE, "AQ");
        try (JsonParser p = createDataInputParser(f, json2)) {
            byte[] data = decodeWithGetBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01 }, data);
        }
        try (JsonParser p = createDataInputParser(f, json2)) {
            byte[] data = decodeWithReadBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01 }, data);
        }

        String json3 = String.format(JSON_TEMPLATE, "AQI");
        try (JsonParser p = createDataInputParser(f, json3)) {
            byte[] data = decodeWithGetBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01, 0x02 }, data);
        }
        try (JsonParser p = createDataInputParser(f, json3)) {
            byte[] data = decodeWithReadBinaryValue(p, VARIANT_PADDING_ALLOWED);
            assertArrayEquals(new byte[] { 0x01, 0x02 }, data);
        }
    }

    // Verify that when padding is required, missing padding triggers an exception, for both _decodeBase64 and _readBinary
    @Test
    public void testMissingPaddingRequired_throws_Utf8StreamParser() throws Exception {
        JsonFactory f = JsonFactory.builder().build();
        String json2 = String.format(JSON_TEMPLATE, "AQ"); // missing '==' padding
        // getBinaryValue path
        try (JsonParser p = createUtf8StreamParser(f, json2)) {
            advanceToValueString(p);
            try {
                p.getBinaryValue(VARIANT_PADDING_REQUIRED);
                fail("Expected JsonParseException for missing Base64 padding with PADDING_REQUIRED");
            } catch (JsonParseException e) {
                // expected
            }
        }
        // readBinaryValue path
        try (JsonParser p = createUtf8StreamParser(f, json2)) {
            advanceToValueString(p);
            try {
                ByteArrayOutputStream out = new ByteArrayOutputStream();
                p.readBinaryValue(VARIANT_PADDING_REQUIRED, out);
                fail("Expected JsonParseException for missing Base64 padding with PADDING_REQUIRED");
            } catch (JsonParseException e) {
                // expected
            }
        }
    }
}

