package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import org.junit.Test;

import java.io.StringWriter;

import static org.junit.Assert.assertEquals;

/**
 * Tests to verify that FilteringGeneratorDelegate creates a child object context
 * when checkValue(_itemFilter) returns null for writeStartObject() overloads.
 * This ensures correct context nesting and proper handling of subsequent end-object
 * and included elements.
 */
public class FilteringGeneratorDelegateNullChildContextTest {

    /**
     * Custom TokenFilter that:
     * - Includes only the array element at a specific index
     * - Within that included object, includes only a specific property name (as full include)
     */
    static class IndexAndNameFilter extends TokenFilter {
        private final int includeIndex;
        private final String includeName;

        IndexAndNameFilter(int includeIndex, String includeName) {
            this.includeIndex = includeIndex;
            this.includeName = includeName;
        }

        @Override
        public TokenFilter includeElement(int index) {
            // Include only the specified array element; others are filtered out (return null)
            return (index == includeIndex) ? this : null;
        }

        @Override
        public TokenFilter includeProperty(String name) {
            // For the included element, include only the specified property fully
            return includeName.equals(name) ? TokenFilter.INCLUDE_ALL : null;
        }

        @Override
        public TokenFilter filterStartObject() {
            // Keep filtering within the object
            return this;
        }
    }

    @Test
    public void testWriteStartObjectCreatesChildContextOnNullFilter() throws Exception {
        // First array element (index 0) is filtered out -> writeStartObject() must still create child context
        // Second element (index 1) includes property "name" -> should be output
        String json = generateWithStartMethod(StartMethod.NO_ARG);
        assertEquals("[{\"name\":\"second\"}]", json);
    }

    @Test
    public void testWriteStartObjectForValueCreatesChildContextOnNullFilter() throws Exception {
        // Same as above but use writeStartObject(Object forValue) for the first filtered-out element
        String json = generateWithStartMethod(StartMethod.FOR_VALUE);
        assertEquals("[{\"name\":\"second\"}]", json);
    }

    @Test
    public void testWriteStartObjectForValueSizeCreatesChildContextOnNullFilter() throws Exception {
        // Same as above but use writeStartObject(Object forValue, int size) for the first filtered-out element
        String json = generateWithStartMethod(StartMethod.FOR_VALUE_AND_SIZE);
        assertEquals("[{\"name\":\"second\"}]", json);
    }

    enum StartMethod {
        NO_ARG,
        FOR_VALUE,
        FOR_VALUE_AND_SIZE
    }

    private String generateWithStartMethod(StartMethod method) throws Exception {
        JsonFactory factory = new JsonFactory();
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = factory.createGenerator(sw);

        // Include full path so that containers (array/object) leading to a match are written
        TokenFilter filter = new IndexAndNameFilter(1, "name");
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, filter, true, true);

        // Root array
        gen.writeStartArray();

        // First element: filtered out (index 0). This triggers f == null in writeStartObject(...) and must create child context.
        switch (method) {
            case NO_ARG:
                gen.writeStartObject();
                break;
            case FOR_VALUE:
                gen.writeStartObject(new Object());
                break;
            case FOR_VALUE_AND_SIZE:
                gen.writeStartObject(new Object(), 2);
                break;
        }
        // These should not produce output due to filtering, but must not break context handling
        gen.writeFieldName("name");
        gen.writeString("first");
        gen.writeEndObject(); // Must correctly close the (filtered) object context

        // Second element: included (index 1). Should write object with only "name" field included.
        gen.writeStartObject();
        gen.writeFieldName("id"); // not included by filter
        gen.writeNumber(2);
        gen.writeFieldName("name"); // included
        gen.writeString("second");
        gen.writeEndObject();

        // End array and flush
        gen.writeEndArray();
        gen.close();

        return sw.toString();
    }
}

