    /**
     * A TokenFilter that excludes all regular content but requests that empty
     * objects and arrays are included in the output.
     */
    static class KeepEmptyContainersFilter extends TokenFilter {
        @Override
        public boolean includeEmptyArray(boolean contentsFiltered) {
            // Always include empty arrays, regardless of whether they were originally empty
            // or filtered to empty.
            return true;
        }

        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            // Always include empty objects, regardless of whether they were originally empty
            // or filtered to empty.
            return true;
        }
    }

    /**
     * A TokenFilter that keeps default behavior for empty containers (exclude them).
     */
    static class ExcludeEmptyContainersFilter extends TokenFilter {
        // No overrides needed; defaults return false for includeEmptyArray/Object
    }

