package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.IOException;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Tests to verify nextFieldName() properly supports ALLOW_TRAILING_COMMA
 * for both Reader-based and DataInput-based parsers.
 */
public class NextFieldNameTrailingCommaTest {

    @Test
    public void testReaderBased_ObjectTrailingComma_nextFieldNameClosesScope() throws Exception {
        String json = "{ \"a\" : 1, }";
        JsonFactory f = new JsonFactory();
        f.enable(JsonParser.Feature.ALLOW_TRAILING_COMMA);

        JsonParser p = f.createParser(json);

        // Start object
        assertEquals(JsonToken.START_OBJECT, p.nextToken());

        // First field
        assertEquals("a", p.nextFieldName());
        // Value for "a"
        assertEquals(JsonToken.VALUE_NUMBER_INT, p.nextToken());
        assertEquals(1, p.getIntValue());

        // Now, there is a trailing comma before closing '}'. With the feature enabled,
        // nextFieldName() should close scope and return null, setting current token to END_OBJECT.
        String name = p.nextFieldName();
        assertNull(name);
        assertEquals(JsonToken.END_OBJECT, p.getCurrentToken());

        // And end of input
        assertNull(p.nextToken());

        p.close();
    }

    @Test
    public void testReaderBased_ArrayTrailingComma_nextFieldNameClosesScope() throws Exception {
        String json = "[ 1, ]";
        JsonFactory f = new JsonFactory();
        f.enable(JsonParser.Feature.ALLOW_TRAILING_COMMA);

        JsonParser p = f.createParser(json);

        // Start array
        assertEquals(JsonToken.START_ARRAY, p.nextToken());

        // Using nextFieldName() even though we're in an array: it should advance to first value
        // and return null (since there is no field name in arrays).
        String name = p.nextFieldName();
        assertNull(name);
        assertEquals(JsonToken.VALUE_NUMBER_INT, p.getCurrentToken());
        assertEquals(1, p.getIntValue());

        // Now there's a trailing comma followed by closing bracket.
        // nextFieldName() should recognize this and close the array.
        name = p.nextFieldName();
        assertNull(name);
        assertEquals(JsonToken.END_ARRAY, p.getCurrentToken());

        // And end of input
        assertNull(p.nextToken());

        p.close();
    }

    @Test
    public void testDataInput_ObjectTrailingComma_nextFieldNameClosesScope() throws Exception {
        String json = "{ \"a\" : 2, }";
        JsonFactory f = new JsonFactory();
        f.enable(JsonParser.Feature.ALLOW_TRAILING_COMMA);

        JsonParser p = f.createParser(asDataInput(json));

        // Start object
        assertEquals(JsonToken.START_OBJECT, p.nextToken());

        // First field
        assertEquals("a", p.nextFieldName());
        // Value for "a"
        assertEquals(JsonToken.VALUE_NUMBER_INT, p.nextToken());
        assertEquals(2, p.getIntValue());

        // Trailing comma before closing brace should be handled by nextFieldName()
        String name = p.nextFieldName();
        assertNull(name);
        assertEquals(JsonToken.END_OBJECT, p.getCurrentToken());

        // End of input
        assertNull(p.nextToken());

        p.close();
    }

    @Test
    public void testDataInput_ArrayTrailingComma_nextFieldNameClosesScope() throws Exception {
        String json = "[ 3, ]";
        JsonFactory f = new JsonFactory();
        f.enable(JsonParser.Feature.ALLOW_TRAILING_COMMA);

        JsonParser p = f.createParser(asDataInput(json));

        // Start array
        assertEquals(JsonToken.START_ARRAY, p.nextToken());

        // Advance to first value using nextFieldName() (returns null in arrays)
        String name = p.nextFieldName();
        assertNull(name);
        assertEquals(JsonToken.VALUE_NUMBER_INT, p.getCurrentToken());
        assertEquals(3, p.getIntValue());

        // Handle trailing comma before closing bracket
