package com.fasterxml.jackson.core;

import org.junit.Test;

import static org.junit.Assert.*;

public class JsonPointerLastAndAppendTest {

    @Test
    public void testLastReturnsLeafForAppendOperator() {
        JsonPointer pointer = JsonPointer.compile("/score/-");
        JsonPointer leaf = pointer.last();

        assertEquals("Leaf pointer should be '/-'", JsonPointer.compile("/-"), leaf);
        assertEquals("Leaf string should be '/-'", "/-", leaf.toString());

        // Verify it matches a property named "-" (JSON Patch append operator)
        assertTrue("Leaf should potentially match a property", leaf.mayMatchProperty());
        assertEquals("Leaf property name should be '-'", "-", leaf.getMatchingProperty());

        // '-' is not a numeric index
        assertFalse("Leaf should not match an array index", leaf.mayMatchElement());
    }

    @Test
    public void testLastReturnsBarForFooBar() {
        JsonPointer pointer = JsonPointer.compile("/foo/bar");
        JsonPointer leaf = pointer.last();

        assertEquals("Leaf pointer should be '/bar'", JsonPointer.compile("/bar"), leaf);
        assertTrue("Leaf should potentially match a property", leaf.mayMatchProperty());
        assertEquals("Leaf property name should be 'bar'", "bar", leaf.getMatchingProperty());
    }

    @Test
    public void testLastReturnsSameInstanceForSingleSegment() {
        JsonPointer pointer = JsonPointer.compile("/x");
        JsonPointer leaf = pointer.last();

        // For a single-segment pointer, last() should return the same instance
        assertSame("Leaf should be the same instance for single-segment pointer", pointer, leaf);
        assertEquals("Pointer string should remain '/x'", "/x", leaf.toString());
    }

    @Test
    public void testLastForArrayIndex() {
        JsonPointer pointer = JsonPointer.compile("/arr/2");
        JsonPointer leaf = pointer.last();

        assertEquals("Leaf pointer should be '/2'", JsonPointer.compile("/2"), leaf);
        assertTrue("Leaf should match an array index", leaf.mayMatchElement());
        assertEquals("Array index should be 2", 2, leaf.getMatchingIndex());
    }

    @Test
    public void testAppendConcatenationAndTrailingSlashRemoval() {
        // Ensure trailing slash is removed before appending
        JsonPointer baseWithSlash = JsonPointer.compile("/a/");
        JsonPointer extra = JsonPointer.compile("/b");
        JsonPointer combined = baseWithSlash.append(extra);

        assertEquals("Appended pointer should be '/a/b'", JsonPointer.compile("/a/b"), combined);
        assertEquals("/a/b", combined.toString());

        // Also test simple append without trailing slash on the base
        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer extraComposite = JsonPointer.compile("/b/c");
        JsonPointer combined2 = base.append(extraComposite);

        assertEquals("Appended pointer should be '/a/b/c'", JsonPointer.compile("/a/b/c"), combined2);
        assertEquals("/a/b/c", combined2.toString());
    }
}

