    public void testLastOnNestedProperties() {
        JsonPointer pointer = JsonPointer.compile("/foo/bar");
        JsonPointer leaf = pointer.last();
        assertEquals("Leaf of '/foo/bar' should be '/bar'", "/bar", leaf.toString());
        assertTrue("Leaf should match property 'bar'", leaf.matchesProperty("bar"));
        assertFalse("Leaf should not match property 'foo'", leaf.matchesProperty("foo"));
    }

    @Test
    public void testLastOnNumericIndexMatchesElement() {
        JsonPointer pointer = JsonPointer.compile("/arr/3");
        JsonPointer leaf = pointer.last();
        assertEquals("Leaf of '/arr/3' should be '/3'", "/3", leaf.toString());
        assertTrue("Leaf should be able to match element index 3", leaf.mayMatchElement());
        assertTrue("Leaf should match element index 3", leaf.matchesElement(3));
        assertFalse("Leaf should not match element index 2", leaf.matchesElement(2));
    }

    @Test
    public void testLastOnSingleSegmentReturnsSameInstance() {
        JsonPointer pointer = JsonPointer.compile("/x");
        JsonPointer leaf = pointer.last();
        assertSame("For single-segment pointer, last() should return same instance", pointer, leaf);
    }

