package com.fasterxml.jackson.core;

import org.junit.Test;

import static org.junit.Assert.*;

public class VersionSnapshotComparisonTest {

    private static final String GROUP = "com.example";
    private static final String ARTIFACT = "artifact";

    @Test
    public void testSnapshotVsReleaseOrdering() {
        Version release = new Version(1, 0, 0, null, GROUP, ARTIFACT);
        Version snapshotAlpha = new Version(1, 0, 0, "alpha", GROUP, ARTIFACT);

        // Sanity
        assertFalse("Release should not be a snapshot", release.isSnapshot());
        assertTrue("Snapshot should be a snapshot", snapshotAlpha.isSnapshot());

        // Snapshot is considered less than a non-snapshot with same numeric components
        assertTrue("Snapshot should be less than release", snapshotAlpha.compareTo(release) < 0);
        assertTrue("Release should be greater than snapshot", release.compareTo(snapshotAlpha) > 0);

        // Equality across two releases without snapshot info: compareTo should return 0
        // Avoid equals/hashCode due to potential null snapshotInfo handling
        Version release2 = new Version(1, 0, 0, null, GROUP, ARTIFACT);
        assertEquals("Releases with identical components should compare equal", 0, release.compareTo(release2));
    }

    @Test
    public void testSnapshotLexicographicOrdering() {
        Version snapshotAlpha = new Version(1, 0, 0, "alpha", GROUP, ARTIFACT);
        Version snapshotBeta = new Version(1, 0, 0, "beta", GROUP, ARTIFACT);
        Version snapshotAlphaCopy = new Version(1, 0, 0, "alpha", GROUP, ARTIFACT);

        // When both are snapshots, compare lexicographically by snapshot info
        assertTrue("alpha should be less than beta for snapshot comparison",
                snapshotAlpha.compareTo(snapshotBeta) < 0);
        assertTrue("beta should be greater than alpha for snapshot comparison",
                snapshotBeta.compareTo(snapshotAlpha) > 0);

        // Equal when snapshot info is identical
        assertEquals("Identical snapshots should compare equal", 0, snapshotAlpha.compareTo(snapshotAlphaCopy));
        assertTrue("Identical snapshots should be equal", snapshotAlpha.equals(snapshotAlphaCopy));
        assertEquals("Equal snapshots must have the same hashCode",
                snapshotAlpha.hashCode(), snapshotAlphaCopy.hashCode());

        // Different snapshot infos should not be equal, and likely have different hashCodes
        assertFalse("Snapshots with different snapshotInfo must not be equal", snapshotAlpha.equals(snapshotBeta));
        assertTrue("Snapshots with different snapshotInfo should normally have different hashCodes",
                snapshotAlpha.hashCode() != snapshotBeta.hashCode());
    }

    @Test
    public void testEqualsConsidersSnapshotInfoAndCompareToPrecedence() {
        Version v1 = new Version(2, 3, 4, "rc1", GROUP, ARTIFACT);
        Version v2 = new Version(2, 3, 4, "rc1", GROUP, ARTIFACT);
        Version v3 = new Version(2, 3, 4, "rc2", GROUP, ARTIFACT);
        Version v4 = new Version(2, 3, 4, null, GROUP, ARTIFACT);

        // Same snapshot info -> equal
        assertTrue("Versions with same snapshotInfo should be equal", v1.equals(v2));
        assertEquals("Equal versions must have equal hashCodes", v1.hashCode(), v2.hashCode());

        // Different snapshot info -> not equal
        assertFalse("Versions with different snapshotInfo should not be equal", v1.equals(v3));

        // Snapshot vs non-snapshot -> compareTo ordering (avoid equals due to null snapshotInfo)
        assertTrue("Pre-release should have lower precedence than release", v1.compareTo(v4) < 0);
        assertTrue("Release should have higher precedence than pre-release", v4.compareTo(v1) > 0);
    }

    @Test
    public void testNumericPrecedenceOverridesSnapshotComparison() {
        Version higherNumericSnapshot = new Version(1, 0, 1, "alpha", GROUP, ARTIFACT);
        Version lowerNumericRelease = new Version(1, 0, 0, null, GROUP, ARTIFACT);

