        assertTrue("Higher patch version should be greater regardless of snapshot",
                higherNumericSnapshot.compareTo(lowerNumericRelease) > 0);
        assertTrue("Lower patch version should be less regardless of snapshot",
                lowerNumericRelease.compareTo(higherNumericSnapshot) < 0);
    }
}

