import java.io.StringWriter;
import java.util.HashSet;
import java.util.Set;

import static org.junit.Assert.assertEquals;

/**
 * Tests ensuring FilteringGeneratorDelegate creates a child object context
 * when checkValue(...) returns null for writeStartObject overloads,
 * and that nothing is written when item filter is null at the current level.
 *
 * Adjusted to:
 * - Use includePath=true so array brackets are written only as needed for included elements
 * - Avoid returning INCLUDE_ALL at the root, which would otherwise include all array elements
 */
public class FilteringGeneratorDelegateNullFilterStartObjectTest {

    /**
     * TokenFilter that includes only specific array element indices by returning INCLUDE_ALL,
     * and returns null for others to simulate filtered-out elements.
     * Does not force INCLUDE_ALL at root to avoid including all elements.
     */
    private static class IncludeOnlyIndexFilter extends TokenFilter {
        private final Set<Integer> includeIndices;

        IncludeOnlyIndexFilter(int... indices) {
            this.includeIndices = new HashSet<>();
            for (int i : indices) {
                this.includeIndices.add(i);
            }
        }

        @Override
        public TokenFilter includeElement(int index) {
            return includeIndices.contains(index) ? TokenFilter.INCLUDE_ALL : null;
        }
    }

    /**
     * TokenFilter that returns a non-INCLUDE_ALL child filter for included indices.
     * The child filter promotes to INCLUDE_ALL only when an object is started via filterStartObject(),
     * exercising the branch where f != INCLUDE_ALL initially.
     */
    private static class IncludeIndexViaChildObjectFilter extends TokenFilter {
        private final Set<Integer> includeIndices;
        private final TokenFilter childFilter = new TokenFilter() {
            @Override
            public TokenFilter filterStartObject() {
                return TokenFilter.INCLUDE_ALL;
            }
        };

        IncludeIndexViaChildObjectFilter(int... indices) {
            this.includeIndices = new HashSet<>();
            for (int i : indices) {
                this.includeIndices.add(i);
            }
        }

        @Override
        public TokenFilter includeElement(int index) {
            return includeIndices.contains(index) ? childFilter : null;
        }
    }

    @Test
    public void testWriteStartObject_noArgs_createsChildContextWhenFilteredOut() throws Exception {
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        // Include only the first element of the root array (index 0)
        TokenFilter filter = new IncludeOnlyIndexFilter(0);
        // includePath=true so the array brackets are written for included elements
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, filter, true, true);

        gen.writeStartArray();

        // First element: included -> should write {}
        gen.writeStartObject();
        gen.writeEndObject();

        // Second element: filtered out -> must still create child context and not write anything
        gen.writeStartObject();
        gen.writeEndObject();

        gen.writeEndArray();
        gen.close();

        assertEquals("[{}]", sw.toString());
    }

    @Test
    public void testWriteStartObject_forValue_createsChildContextWhenFilteredOut() throws Exception {
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        TokenFilter filter = new IncludeOnlyIndexFilter(0);
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, filter, true, true);

        gen.writeStartArray();

        // First element: included
        gen.writeStartObject(new Object());
        gen.writeEndObject();

        // Second element: filtered out -> must still create child context and not write anything
        gen.writeStartObject(new Object());
        gen.writeEndObject();

        gen.writeEndArray();
        gen.close();

        assertEquals("[{}]", sw.toString());
    }

    @Test
    public void testWriteStartObject_forValueAndSize_createsChildContextWhenFilteredOut() throws Exception {
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        // Use a filter that initially returns a child filter (not INCLUDE_ALL) and promotes on object start
        TokenFilter filter = new IncludeIndexViaChildObjectFilter(0);
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, filter, true, true);

        gen.writeStartArray();

        // First element: included via child filter that promotes on filterStartObject()
        gen.writeStartObject(new Object(), 0);
