        // Second element: filtered out -> must still create child context and not write anything
        gen.writeStartObject(new Object(), 0);
        gen.writeEndObject();

        gen.writeEndArray();
        gen.close();

        assertEquals("[{}]", sw.toString());
    }

    @Test
    public void testWriteStartObject_forValueAndSize_withNullItemFilter_noWritesButNoFailure() throws Exception {
        // Covers the branch where _itemFilter == null in writeStartObject(forValue, size)
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        // Construct with null filter: entire output should be filtered out
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, null, true, true);

        // Start/end an object using the size overload: should create a child context and write nothing
        gen.writeStartObject(new Object(), 0);
        gen.writeEndObject();

        gen.close();

        assertEquals("", sw.toString());
    }
}

