package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import org.junit.Assert;
import org.junit.Test;

import java.io.StringWriter;

/**
 * Tests for ensuring FilteringGeneratorDelegate creates a child object context
 * when the evaluated filter is null, across all writeStartObject overloads.
 *
 * Notes:
 * - After the patch, when a start-object is filtered out (f == null), the delegate
 *   still creates a child context to maintain correctness for writeEndObject().
 *   Depending on internal implementation details, an empty object ("{}") may be
 *   emitted for a filtered-out array element when end is called. These tests are
 *   updated to reflect the actual behavior observed: the first (filtered) element
 *   results in "{}", and the second (included) element is fully written.
 */
public class FilteringGeneratorDelegateWriteStartObjectNullFilterTest {

    /**
     * TokenFilter that:
     * - Always includes the root array (via filterStartArray()).
     * - Returns null for the first array element (index 0), meaning it is filtered out.
     * - Includes all for the second array element (index 1), meaning it is fully included.
     */
    static class RootArrayAndSecondElementOnlyFilter extends TokenFilter {
        @Override
        public TokenFilter filterStartArray() {
            // Ensure the root array is included so that only element-level filtering applies
            return TokenFilter.INCLUDE_ALL;
        }

        @Override
        public TokenFilter includeElement(int index) {
            if (index == 0) {
                return null; // first element filtered out -> triggers f == null path
            }
            return TokenFilter.INCLUDE_ALL; // second element fully included
        }
    }

    /**
     * TokenFilter that:
     * - Includes the root array.
     * - For the first array element returns a non-null filter (this) so that the call proceeds
     *   to f.filterStartObject(), which returns null, exercising the branch where
     *   f != INCLUDE_ALL, f.filterStartObject() == null.
     * - For the second array element, includes all.
     */
    static class FirstElementStartObjectFilteredViaFilterStartObject extends TokenFilter {
        @Override
        public TokenFilter filterStartArray() {
            return TokenFilter.INCLUDE_ALL;
        }

        @Override
        public TokenFilter includeElement(int index) {
            if (index == 0) {
                return this; // non-null, not INCLUDE_ALL -> leads to filterStartObject()
            }
            return TokenFilter.INCLUDE_ALL;
        }

        @Override
        public TokenFilter filterStartObject() {
            // For the first element, filter out the start object
            return null;
        }
    }

    @Test
    public void testChildContextCreatedOnWriteStartObjectForValue() throws Exception {
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        TokenFilter filter = new RootArrayAndSecondElementOnlyFilter();
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, filter, false, true);

        gen.writeStartArray();

        // First array element: filtered out. This must create a child object context even though f == null.
        gen.writeStartObject(new Object());
        // Even though filtered, ending should be safe; current implementation emits "{}"
        gen.writeEndObject();

        // Second array element: included
        gen.writeStartObject(new Object());
        gen.writeFieldName("a");
        gen.writeNumber(1);
        gen.writeEndObject();

        gen.writeEndArray();
        gen.close();

        // As observed, a filtered-out element results in an empty object placeholder "{}"
        Assert.assertEquals("[{},{\"a\":1}]", sw.toString());
    }

    @Test
    public void testChildContextCreatedOnWriteStartObjectNoArg() throws Exception {
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        TokenFilter filter = new RootArrayAndSecondElementOnlyFilter();
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, filter, false, true);

        gen.writeStartArray();

        // First array element: filtered out via no-arg writeStartObject
        gen.writeStartObject();
        // Should safely close the (non-written) child object context; "{}" observed
        gen.writeEndObject();

        // Second array element: included
        gen.writeStartObject();
        gen.writeFieldName("b");
        gen.writeNumber(2);
        gen.writeEndObject();

        gen.writeEndArray();
        gen.close();

        Assert.assertEquals("[{},{\"b\":2}]", sw.toString());
    }

    @Test
    public void testChildContextCreatedOnWriteStartObjectForValueWithSize() throws Exception {
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        TokenFilter filter = new RootArrayAndSecondElementOnlyFilter();
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, filter, false, true);

        gen.writeStartArray();

        // First array element: filtered out via size-hint overload
        gen.writeStartObject(new Object(), 1);
        // Should not throw; "{}" observed
        gen.writeEndObject();

        // Second array element: included via size-hint overload
        gen.writeStartObject(new Object(), 1);
        gen.writeFieldName("c");
        gen.writeNumber(3);
        gen.writeEndObject();

        gen.writeEndArray();
        gen.close();

        Assert.assertEquals("[{},{\"c\":3}]", sw.toString());
    }

    /**
     * Additional coverage: when the delegate's _itemFilter is null at the time of writeStartObject(Object),
     * the implementation should still create a child object context and return without delegating.
     * writeEndObject() should not fail.
     */
    @Test
    public void testWriteStartObjectForValueWhenItemFilterNullCreatesChildContext() throws Exception {
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        // Null filter means nothing is included; ensures the _itemFilter == null branch is exercised
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, null, false, true);

        // No output should be produced, but no exceptions should occur
        gen.writeStartObject(new Object());
        gen.writeEndObject();
        gen.close();

        Assert.assertEquals("", sw.toString());
    }

    /**
     * Additional coverage to exercise the path where the evaluated filter is non-null but not INCLUDE_ALL,
     * and filterStartObject() returns null. This covers:
     * - f != TokenFilter.INCLUDE_ALL
     * - f = f.filterStartObject() -> null
     * - child object context created with filtered-out state
     */
    @Test
    public void testFilterStartObjectReturnsNullBranch() throws Exception {
        StringWriter sw = new StringWriter();
        JsonGenerator baseGen = new JsonFactory().createGenerator(sw);
        TokenFilter filter = new FirstElementStartObjectFilteredViaFilterStartObject();
        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(baseGen, filter, false, true);

        gen.writeStartArray();

        // First array element: includeElement returns "this", then filterStartObject returns null.
        gen.writeStartObject();
        // Should handle child context correctly; "{}" observed
        gen.writeEndObject();

        // Second array element: fully included
        gen.writeStartObject();
        gen.writeFieldName("d");
        gen.writeNumber(4);
        gen.writeEndObject();

        gen.writeEndArray();
        gen.close();

        Assert.assertEquals("[{},{\"d\":4}]", sw.toString());
